using CashFlow.Launch.Domain.Entities;using CashFlow.Launch.Domain.Entities.Base;using CashFlow.Launch.Domain.Interfaces;using Microsoft.EntityFrameworkCore;
namespace CashFlow.Launch.Infrastructure.Context;public class CashFlowDbContext:DbContext{readonly ITenantContext? _tenant;public Guid CurrentGroupId=>_tenant?.GroupId??Guid.Empty;public bool HasCurrentGroup=>_tenant?.HasGroup==true;public CashFlowDbContext(DbContextOptions<CashFlowDbContext> options,ITenantContext? tenant=null):base(options){_tenant=tenant;}public DbSet<Entry> Entries=>Set<Entry>();public DbSet<OutboxMessage> OutboxMessages=>Set<OutboxMessage>();public DbSet<Account> Accounts=>Set<Account>();public DbSet<Category> Categories=>Set<Category>();public DbSet<RecurringEntry> RecurringEntries=>Set<RecurringEntry>();public DbSet<CreditCard> CreditCards=>Set<CreditCard>();public DbSet<CreditCardPurchase> CreditCardPurchases=>Set<CreditCardPurchase>();public DbSet<CreditCardInstallment> CreditCardInstallments=>Set<CreditCardInstallment>();public DbSet<MonthlyBudget> MonthlyBudgets=>Set<MonthlyBudget>();protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<Entry>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<Account>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<Category>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<RecurringEntry>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<CreditCard>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<CreditCardPurchase>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<CreditCardInstallment>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<MonthlyBudget>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);b.Entity<OutboxMessage>().HasQueryFilter(x=>!HasCurrentGroup||x.GroupId==CurrentGroupId);}public override int SaveChanges(){ApplyTenant();return base.SaveChanges();}public override Task<int> SaveChangesAsync(CancellationToken ct=default){ApplyTenant();return base.SaveChangesAsync(ct);}void ApplyTenant(){if(!HasCurrentGroup)return;foreach(var e in ChangeTracker.Entries<Entity>().Where(x=>x.State==EntityState.Added))e.Entity.GroupId=CurrentGroupId;}}